1.reproduce_code:
// package.json
{
  "name": "carbon-datatable-destructure-bug",
  "version": "0.1.0",
  "private": true,
  "dependencies": {
    "react": "17.0.0",
    "react-dom": "17.0.0",
    "@carbon/react": "1.23.0-rc.0"
  },
  "scripts": {
    "start": "react-scripts start"
  }
}

// src/index.js
import React from 'react';
import ReactDOM from 'react-dom';
import App from './App';

ReactDOM.render(<App />, document.getElementById('root'));

// src/App.jsx
import React from 'react';
import { DataTable } from '@carbon/react';

// ❌ This destructuring will break because DataTable.* is undefined in v11
const {
  TableContainer,
  Table,
  TableHead,
  TableRow,
  TableHeader,
  TableBody,
  TableCell,
} = DataTable;

// minimal rows + headers data
typedef Rows = Array<{ id: string; name: string; status: string }>;
const rows = [
  { id: 'a', name: 'Load balancer A', status: 'Active' },
  { id: 'b', name: 'Load balancer B', status: 'Disabled' },
];
const headers = [
  { key: 'name', header: 'Name' },
  { key: 'status', header: 'Status' },
];

export default function App() {
  return (
    <div style={{ padding: '2rem' }}>
      <h2>DataTable with destructure bug</h2>
      <DataTable rows={rows} headers={headers}>
        {({ rows, headers, getTableProps, getHeaderProps, getRowProps }) => (
          <TableContainer title="Example" description="Destructuring failure">
            <Table {...getTableProps()}>
              <TableHead>
                <TableRow>
                  {headers.map((hdr) => (
                    <TableHeader key={hdr.key} {...getHeaderProps({ header: hdr })}>
                      {hdr.header}
                    </TableHeader>
                  ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {rows.map((row) => (
                  <TableRow key={row.id} {...getRowProps({ row })}>
                    {row.cells.map((cell) => (
                      <TableCell key={cell.id}>{cell.value}</TableCell>
                    ))}
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}
      </DataTable>
    </div>
  );
}

// When you run `npm start`, you will see red console errors:
// "Warning: React.createElement: type is invalid — expected a string ... but got: undefined"
// This reproduces the exact issue from the bug report.

1.bug_scenario:
In v11 of @carbon/react (e.g. version 1.23.0-rc.0) the DataTable component no longer exposes its child components as static properties. In the screenshots you can see the developer imports DataTable, then writes:

  const { TableContainer, Table, TableHead, TableRow, TableHeader, TableBody, TableCell } = DataTable;

and then attempts to render <TableContainer> inside the render-prop of <DataTable>. Because DataTable.TableContainer is undefined, all of the destructured variables are undefined and React.createElement blows up with "Element type is invalid" errors, breaking the whole app. When you comment out the destructuring and instead import the components directly from '@carbon/react', the table renders successfully.
